/// Check if a timezone name is valid
fn vm_is_valid_timezone(tz_name: &str) -> bool {
    if tz_name.is_empty() {
        return false;
    }
    // Known timezone names
    let known = [
        "UTC",
        "GMT",
        "CET",
        "EET",
        "MET",
        "WET",
        "PRC",
        "ROC",
        "ROK",
        "NZ",
        "GB",
        "Japan",
        "Iceland",
        "Zulu",
        "US/Eastern",
        "US/Central",
        "US/Mountain",
        "US/Pacific",
        "US/Hawaii",
        "US/Alaska",
        "Canada/Atlantic",
        "Canada/Eastern",
        "Canada/Central",
        "Canada/Mountain",
        "Canada/Pacific",
        "Canada/Newfoundland",
    ];
    if known.iter().any(|k| k.eq_ignore_ascii_case(tz_name)) {
        return true;
    }
    // Named timezone with / (e.g., America/New_York)
    if tz_name.contains('/') {
        let parts: Vec<&str> = tz_name.split('/').collect();
        if parts.len() >= 2 {
            let region = parts[0];
            let valid_regions = [
                "Africa",
                "America",
                "Antarctica",
                "Arctic",
                "Asia",
                "Atlantic",
                "Australia",
                "Europe",
                "Indian",
                "Pacific",
                "Etc",
            ];
            return valid_regions.iter().any(|r| r.eq_ignore_ascii_case(region));
        }
    }
    // Offset format
    if vm_parse_tz_offset(tz_name).is_some() {
        return true;
    }
    // Named abbreviations (e.g., "EST", "PST")
    if vm_is_tz_abbrev(tz_name) {
        return true;
    }
    false
}

/// The names of `props` (a class's own declarations, in order), for
/// `ClassEntry::own_prop_order`.
#[inline(never)]
fn own_prop_order(props: &[crate::object::PropertyDef]) -> Vec<Vec<u8>> {
    props.iter().map(|p| p.name.clone()).collect()
}

/// The names of a class's constants whose value is a deferred constant
/// reference (`__deferred_const__::Class::NAME`), in order.
#[inline(never)]
fn deferred_const_keys(class: &crate::object::ClassEntry) -> Vec<Vec<u8>> {
    class
        .constants
        .iter()
        .filter(|(_, v)| {
            matches!(v, Value::String(s) if s.as_bytes().starts_with(b"__deferred_const__::"))
        })
        .map(|(k, _)| k.clone())
        .collect()
}

/// Backed properties are considered to always implicitly implement get and
/// set when they don't define them (zend_inheritance.c inherit_property_hook()):
/// drop the inherited abstract hook methods of a backed hooked property.
#[inline(never)]
fn drop_backed_abstract_hooks(class: &mut crate::object::ClassEntry) {
    let names: Vec<Vec<u8>> = class
        .properties
        .iter()
        .filter(|p| {
            !p.is_abstract && !p.is_virtual && !p.is_static && (p.has_get_hook || p.has_set_hook)
        })
        .map(|p| p.name.to_ascii_lowercase())
        .collect();
    for n in names {
        for pre in [b"__property_get_".as_slice(), b"__property_set_".as_slice()] {
            let key = [pre, n.as_slice()].concat();
            if class.methods.get(&key).is_some_and(|m| m.is_abstract) {
                class.methods.swap_remove(&key);
            }
        }
    }
}

/// Whether `op` is a write fetch of `$GLOBALS['this']` (the frame's
/// $GLOBALS CV is `globals`).
#[inline(never)]
fn globals_dim_write_this(
    op: &crate::opcode::Op,
    globals: u32,
    cvs: &[Value],
    tmps: &[Value],
    literals: &[Value],
) -> bool {
    if op.op1 != OperandType::Cv(globals) {
        return false;
    }
    let key = match op.opcode {
        OpCode::ArraySet | OpCode::ArraySetRef | OpCode::ArraySetIncDec => &op.result,
        OpCode::ArrayGetRW
        | OpCode::ArrayGetRef
        | OpCode::ArrayGetW
        | OpCode::ArrayGetWRW
        | OpCode::ArrayGetIncDec
        | OpCode::ArrayGetWObj
        | OpCode::ArrayGetWObjRW
        | OpCode::ArrayGetObjW => &op.op2,
        _ => return false,
    };
    let v = match key {
        OperandType::Const(i) => literals.get(*i as usize),
        OperandType::Cv(i) => cvs.get(*i as usize),
        OperandType::Tmp(i) => tmps.get(*i as usize),
        _ => None,
    };
    matches!(v.map(|v| v.deref()), Some(Value::String(s)) if s.as_bytes() == b"this")
}

impl Vm {
    /// `parent::$prop::get()` / `::set()` where the parent's property is
    /// private: "Cannot access private property P::$prop".
    #[inline(never)]
    fn parent_hook_private_error(&self, name: &[u8], op_array: &OpArray) -> Option<String> {
        let rest = &name[b"parent::__property_".len()..];
        let prop = rest
            .strip_prefix(b"get_".as_slice())
            .or_else(|| rest.strip_prefix(b"set_".as_slice()))?;
        let scope = op_array.scope_class.as_ref()?;
        let parent = self
            .classes
            .get(&scope.to_ascii_lowercase())?
            .parent
            .clone()?;
        let pl = parent.to_ascii_lowercase();
        let (vis, decl, ..) = self.find_property_def(&pl, prop)?;
        if vis != Visibility::Private {
            return None;
        }
        let pd = self
            .classes
            .get(&pl)
            .map(|c| crate::value::display_class_name(&c.name))
            .unwrap_or_else(|| crate::value::display_class_name(&decl));
        Some(format!(
            "Cannot access private property {}::${}",
            pd,
            String::from_utf8_lossy(prop)
        ))
    }
}
